    @SuppressWarnings("unused")
    public List<Reservation> findAll( FindAllReservationQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Reservation - {0}", exc.getMessage() );
    	}
    	return null;
    }


